import { motion } from 'framer-motion';

export default function Card({ children, className = '', delay = 0, hover = false }) {
  const safeClassName = typeof className === 'string' ? className : '';

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4, delay, ease: 'easeOut' }}
      className={`bg-white rounded-xl border border-slate-200 card-shadow ${
        hover ? 'hover:-translate-y-1 hover:card-shadow-hover hover:border-blue-200 transition-all duration-200 cursor-pointer' : ''
      } ${safeClassName}`}
    >
      {children}
    </motion.div>
  );
}

import { motion } from 'framer-motion';

export default function GlassCard({ children, className = '', delay = 0, hover = true }) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay, ease: 'easeOut' }}
      className={`glass rounded-2xl p-6 ${hover ? 'glass-hover hover:border-indigo-500/30 hover:shadow-indigo-500/5' : ''} ${className}`}
    >
      {children}
    </motion.div>
  );
}

import { motion } from 'framer-motion';
import { useEffect } from 'react';

export default function LoadingScreen({ onComplete }) {
  useEffect(() => {
    const timer = setTimeout(() => {
      onComplete();
    }, 1500); 
    return () => clearTimeout(timer);
  }, [onComplete]);

  return (
    <motion.div
      initial={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={{ duration: 0.4, ease: "easeInOut" }}
      className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-slate-50"
    >
      <motion.div 
        initial={{ scale: 0.95, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        transition={{ duration: 0.4 }}
        className="flex flex-col items-center"
      >
        <div className="w-16 h-16 rounded-2xl bg-blue-600 flex items-center justify-center mb-6 shadow-lg shadow-blue-600/20">
          <span className="text-2xl font-bold text-white">PT</span>
        </div>

        <h1 className="text-xl font-bold text-slate-800 tracking-wide mb-8">PlaceTrack</h1>

        <div className="w-48 h-1.5 bg-slate-200 rounded-full overflow-hidden">
          <motion.div 
            initial={{ width: "0%" }}
            animate={{ width: "100%" }}
            transition={{ duration: 1.2, ease: "easeInOut" }}
            className="h-full bg-blue-600 rounded-full"
          ></motion.div>
        </div>
      </motion.div>
    </motion.div>
  );
}

import { motion } from 'framer-motion';

export default function Skeleton({ className = "", shape = "rect" }) {
  const safeClassName = typeof className === 'string' ? className : '';
  const baseClasses = "bg-slate-200 animate-pulse relative overflow-hidden";
  const shapeClasses = shape === 'circle' ? 'rounded-full' : 'rounded-lg';

  return (
    <div className={`${baseClasses} ${shapeClasses} ${safeClassName}`}>
      <motion.div
        className="absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/40 to-transparent z-10"
        animate={{ translateX: ['-100%', '200%'] }}
        transition={{ duration: 1.5, repeat: Infinity, ease: 'easeInOut' }}
      />
    </div>
  );
}

import { useEffect, useState } from 'react';
import Card from './Card';
import Skeleton from './Skeleton';

export default function StatCard({ title, value, icon: Icon, delay, prefix = '', suffix = '', trend, isLoading = false }) {
  const [currentValue, setCurrentValue] = useState(0);

  useEffect(() => {
    if (isLoading) return;

    let start = 0;
    const end = typeof value === 'string' ? parseFloat(value.replace(/,/g, '')) : value;
    if (isNaN(end)) return;

    const duration = 1000;
    const incrementTime = 30;
    const steps = duration / incrementTime;
    const increment = end / steps;

    const timer = setInterval(() => {
      start += increment;
      if (start >= end) {
        clearInterval(timer);
        setCurrentValue(end);
      } else {
        setCurrentValue(Number.isInteger(end) ? Math.ceil(start) : Number(start.toFixed(1)));
      }
    }, incrementTime);

    return () => clearInterval(timer);
  }, [value, isLoading]);

  if (isLoading) {
    return (
      <Card delay={0.1} className="h-[140px] flex flex-col justify-between">
        <div className="flex justify-between items-start mb-2">
          <Skeleton className="w-11 h-11 rounded-lg" />
          {trend && <Skeleton className="w-12 h-6 rounded-md" />}
        </div>
        <div>
          <Skeleton className="w-20 h-4 mb-2" />
          <Skeleton className="w-24 h-8" />
        </div>
      </Card>
    );
  }

  const displayValue = isNaN(parseFloat(value)) 
    ? value 
    : (Number.isInteger(currentValue) ? currentValue.toLocaleString() : currentValue);

  return (
    <Card delay={delay} hover={false} className="h-[140px] flex flex-col justify-between">
      <div className="flex justify-between items-start mb-2">
        <div className="p-2.5 bg-blue-50 rounded-lg text-blue-600 ring-1 ring-blue-100">
          <Icon size={20} className="stroke-[2.5]" />
        </div>
        {trend && (
          <span className={`text-xs font-semibold px-2 py-1 rounded-md ${trend > 0 ? 'bg-green-50 text-green-700 ring-1 ring-green-200' : 'bg-red-50 text-red-700 ring-1 ring-red-200'}`}>
            {trend > 0 ? '+' : ''}{trend}%
          </span>
        )}
      </div>

      <div>
        <h3 className="text-slate-500 text-sm font-medium mb-1">{title}</h3>
        <div className="flex items-baseline gap-1">
          {prefix && <span className="text-lg font-semibold text-slate-700">{prefix}</span>}
          <div className="text-3xl font-bold text-slate-800 tracking-tight">
            {displayValue}
          </div>
          {suffix && <span className="text-lg font-semibold text-slate-600">{suffix}</span>}
        </div>
      </div>
    </Card>
  );
}

